const data = $input.first().json;
let chat_id, user_id, text, callback_data, is_callback, callback_id;
if (data.callback_query) {
  const cb = data.callback_query;
  chat_id = String(cb.message.chat.id);
  user_id = String(cb.from.id);
  text = '';
  callback_data = cb.data || '';
  callback_id = cb.id || '';
  is_callback = true;
} else if (data.message) {
  const msg = data.message;
  chat_id = String(msg.chat.id);
  user_id = String(msg.from.id);
  text = (msg.text || '').trim();
  callback_data = '';
  callback_id = '';
  is_callback = false;
} else {
  chat_id = ''; user_id = ''; text = '';
  callback_data = ''; callback_id = ''; is_callback = false;
}
return [{ json: { chat_id, user_id, text, callback_data, is_callback, callback_id } }];

const input = $('Code: Parse Input').first().json;
const stateRows = $('PostgreSQL: Get State').all();
const userState = (stateRows.length > 0 && stateRows[0].json && stateRows[0].json.state) ? stateRows[0].json.state : null;
const { chat_id, user_id, text, callback_data, is_callback, callback_id } = input;

let route = 'simple_reply';
let reply_text = 'Неизвестная команда. Используйте /start для справки.';
let query = '';
let action_query = '';
let state_name = '';
let list_mode = '';
let entity = '';
let table_name = '';

if (is_callback && callback_data) {
  if (callback_data === 'add_channel') {
    route = 'set_state'; state_name = 'waiting_for_channel';
    reply_text = 'Отправьте URL канала (например: https://t.me/channel_name)';
  } else if (callback_data === 'add_interest') {
    route = 'set_state'; state_name = 'waiting_for_interest';
    reply_text = 'Отправьте текст интереса (ключевое слово или фразу):';
  } else if (callback_data === 'add_style') {
    route = 'set_state'; state_name = 'waiting_for_style';
    reply_text = 'Отправьте пример поста в вашем стиле:';
  } else if (callback_data === 'delete_channels') {
    route = 'show_list'; list_mode = 'delete'; entity = 'channel'; table_name = 'channels';
    query = 'SELECT id, url AS display FROM channels ORDER BY id';
  } else if (callback_data === 'delete_interests') {
    route = 'show_list'; list_mode = 'delete'; entity = 'interest'; table_name = 'interests';
    query = 'SELECT id, text AS display FROM interests ORDER BY id';
  } else if (callback_data === 'delete_styles') {
    route = 'show_list'; list_mode = 'delete'; entity = 'style'; table_name = 'styles';
    query = 'SELECT id, LEFT(text, 50) AS display FROM styles ORDER BY id';
  } else if (callback_data.startsWith('del_ch_')) {
    route = 'db_action';
    action_query = `DELETE FROM channels WHERE id = ${parseInt(callback_data.split('_')[2])}`;
    reply_text = 'Канал удалён.';
  } else if (callback_data.startsWith('del_int_')) {
    route = 'db_action';
    action_query = `DELETE FROM interests WHERE id = ${parseInt(callback_data.split('_')[2])}`;
    reply_text = 'Интерес удалён.';
  } else if (callback_data.startsWith('del_st_')) {
    route = 'db_action';
    action_query = `DELETE FROM styles WHERE id = ${parseInt(callback_data.split('_')[2])}`;
    reply_text = 'Стиль удалён.';
  }
} else if (userState) {
  const cmd = (text || '').split('@')[0];
  if (cmd === '/cancel') {
    route = 'db_action';
    action_query = 'SELECT 1';
    reply_text = 'Действие отменено.';
  } else if (userState === 'waiting_for_channel') {
    route = 'db_action';
    const safeUrl = text.split(`'`).join(`''`).replace(/\s+/g, '');
    action_query = `INSERT INTO channels (url) VALUES ('${safeUrl}') ON CONFLICT (url) DO NOTHING`;
    reply_text = 'Канал добавлен.';
  } else if (userState === 'waiting_for_interest') {
    route = 'db_action';
    const safe = text.split(`'`).join(`''`);
    action_query = `INSERT INTO interests (text) VALUES ('${safe}')`;
    reply_text = 'Интерес добавлен.';
  } else if (userState === 'waiting_for_style') {
    route = 'db_action';
    const safe = text.split(`'`).join(`''`);
    action_query = `INSERT INTO styles (text) VALUES ('${safe}')`;
    reply_text = 'Стиль добавлен.';
  } else if (userState === 'waiting_for_digest_time') {
    if (/^([01]\d|2[0-3]):([0-5]\d)$/.test(text)) {
      route = 'db_action';
      action_query = `UPDATE settings SET value = '${text}' WHERE key = 'digest_time'`;
      reply_text = `Время дайджеста установлено: ${text} МСК`;
    } else {
      route = 'simple_reply';
      reply_text = 'Неверный формат. Отправьте время в формате HH:MM (например: 09:00)';
    }
  } else if (userState === 'waiting_for_post_ids') {
    const ids = text.split(/\s+/).map(s => parseInt(s)).filter(n => !isNaN(n) && n > 0);
    if (ids.length === 0) {
      route = 'simple_reply';
      reply_text = 'Не удалось распознать id постов. Отправьте числа через пробел (например: 1 2 3) или /cancel для отмены.';
    } else {
      route = 'generate_post';
    }
  }
} else {
  const cmd = (text || '').split('@')[0];
  if (cmd === '/start') {
    route = 'simple_reply';
    reply_text = `Привет! Я помогу собирать новости из Telegram-каналов.\n\nКоманды:\n/set_channels — управление каналами\n/set_interests — управление интересами\n/set_style — управление стилями постов\n/set_digest_time — время дайджеста\n/generate_post — генерация поста\n/cancel — отмена текущего действия`;
  } else if (cmd === '/set_channels') {
    route = 'show_list'; list_mode = 'view'; entity = 'channel'; table_name = 'channels';
    query = 'SELECT id, url AS display FROM channels ORDER BY id';
  } else if (cmd === '/set_interests') {
    route = 'show_list'; list_mode = 'view'; entity = 'interest'; table_name = 'interests';
    query = 'SELECT id, text AS display FROM interests ORDER BY id';
  } else if (cmd === '/set_style') {
    route = 'show_list'; list_mode = 'view'; entity = 'style'; table_name = 'styles';
    query = 'SELECT id, LEFT(text, 50) AS display FROM styles ORDER BY id';
  } else if (cmd === '/set_digest_time') {
    route = 'set_state'; state_name = 'waiting_for_digest_time';
    reply_text = 'Отправьте время в формате HH:MM (например: 09:00). Таймзона: МСК.';
  } else if (cmd === '/generate_post') {
    route = 'set_state'; state_name = 'waiting_for_post_ids';
    reply_text = 'Отправьте id постов из дайджеста через пробел (например: 1 2 3 5 12)';
  } else if (cmd === '/cancel') {
    route = 'simple_reply';
    reply_text = 'Нет активного действия для отмены.';
  }
}

return [{ json: { route, chat_id, user_id, text, reply_text, query, action_query, state_name, list_mode, entity, table_name, callback_id, is_callback } }];

const items = $input.all().map(i => i.json);
const meta = $('Code: Route').first().json;
const { chat_id, entity, table_name } = meta;

let message = '';
if (items.length === 0 || (items.length === 1 && !items[0].id)) {
  message = 'Список пуст.';
} else {
  items.forEach(item => {
    message += `#${item.id}: ${item.display}\n`;
  });
}
const add_callback = `add_${entity}`;
const delete_callback = `delete_${table_name}`;
return [{ json: { chat_id, message, add_callback, delete_callback } }];

const items = $input.all().map(i => i.json);
const meta = $('Code: Route').first().json;
const { chat_id, entity } = meta;
const prefix = entity === 'channel' ? 'del_ch_' : entity === 'interest' ? 'del_int_' : 'del_st_';

let text = 'Список пуст.';
let keyboard = [];
if (items.length > 0 && items[0].id) {
  text = 'Выберите элемент для удаления:';
  keyboard = items.map(item => ([
    { text: `#${item.id}: ${item.display}`, callback_data: `${prefix}${item.id}` }
  ]));
}
const body = { chat_id: Number(chat_id), text, reply_markup: { inline_keyboard: keyboard } };
return [{ json: { body: JSON.stringify(body) } }];

const meta = $('Code: Route').first().json;
const { text, chat_id, user_id } = meta;
const ids = text.split(/\s+/).map(s => parseInt(s)).filter(n => !isNaN(n) && n > 0);
if (ids.length === 0) {
  throw new Error('Не удалось распознать id постов. Отправьте числа через пробел.');
}
return [{ json: { ids, ids_str: ids.join(','), chat_id, user_id } }];

const posts = $('PostgreSQL: Get Posts').all().map(i => i.json);
const styles = $('PostgreSQL: Get Styles').all().map(i => i.json.text);
const meta = $('Code: Parse Post IDs').first().json;
return [{ json: { posts: JSON.stringify(posts), styles: JSON.stringify(styles), chat_id: meta.chat_id, user_id: meta.user_id } }];

const raw = $input.first().json.message?.content || $input.first().json.text || '';
const meta = $('Code: Prepare AI').first().json;
return [{ json: { chat_id: meta.chat_id, user_id: meta.user_id, post_text: raw } }];
